def LocalRefine(self, x_repaired, local_ops, params):
    # Apply a few local search iterations: relocate, swap, 2-opt across routes
    routes = self._flat_to_routes(x_repaired)
    improved = True
    iter_lim = 5
    while improved and iter_lim > 0:
        improved = False
        iter_lim -= 1
        # relocate: move one node to better route/position
        for i, r_from in enumerate(routes):
            for idx in range(1, len(r_from) - 1):
                node = r_from[idx]
                for j, r_to in enumerate(routes):
                    if i == j:
                        continue
                    # try insert in best position in r_to
                    best_pos = None
                    best_delta = 0
                    for pos in range(1, len(r_to)):
                        # compute delta cost if move node here
                        # remove from r_from
                        rf = r_from
                        cost_before = self._route_cost(r_from) + self._route_cost(r_to)
                        new_rf = rf[:idx] + rf[idx+1:]
                        new_rt = r_to[:pos] + [node] + r_to[pos:]
                        # check capacity
                        load_new_rt = sum(self.demands[x] for x in new_rt if x != self.depot)
                        load_new_rf = sum(self.demands[x] for x in new_rf if x != self.depot)
                        if load_new_rt > self.vehicle_capacity or load_new_rf > self.vehicle_capacity:
                            continue
                        cost_after = self._route_cost(new_rf) + self._route_cost(new_rt)
                        delta = cost_after - cost_before
                        if delta < best_delta:
                            best_delta = delta
                            best_pos = (j, pos, new_rf, new_rt)
                    if best_pos:
                        j, pos, new_rf, new_rt = best_pos
                        routes[i] = new_rf
                        routes[j] = new_rt
                        improved = True
                        break
                if improved:
                    break
            if improved:
                break
        # pairwise swap nodes between routes
        if not improved:
            for a in range(len(routes)):
                for b in range(a+1, len(routes)):
                    ra, rb = routes[a], routes[b]
                    for ia in range(1, len(ra)-1):
                        for ib in range(1, len(rb)-1):
                            na, nb = ra[ia], rb[ib]
                            load_a = sum(self.demands[x] for x in ra if x != self.depot) - self.demands[na] + self.demands[nb]
                            load_b = sum(self.demands[x] for x in rb if x != self.depot) - self.demands[nb] + self.demands[na]
                            if load_a > self.vehicle_capacity or load_b > self.vehicle_capacity:
                                continue
                            cost_before = self._route_cost(ra) + self._route_cost(rb)
                            new_ra = ra[:ia] + [nb] + ra[ia+1:]
                            new_rb = rb[:ib] + [na] + rb[ib+1:]
                            cost_after = self._route_cost(new_ra) + self._route_cost(new_rb)
                            if cost_after < cost_before - 1e-6:
                                routes[a], routes[b] = new_ra, new_rb
                                improved = True
                                break
                        if improved:
                            break
                    if improved:
                        break
                if improved:
                    break
        # 2-opt within routes
        if not improved:
            for i, r in enumerate(routes):
                L = len(r)
                for a in range(1, L - 2):
                    for b in range(a+1, L - 1):
                        newr = r[:a] + list(reversed(r[a:b+1])) + r[b+1:]
                        if self._route_cost(newr) + 1e-9 < self._route_cost(r):
                            routes[i] = newr
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
    return self._routes_to_flat(routes)

# Your key function here
def _route_cost(self, route):
    """Compute route cost using vectorized numpy indexing for speed."""
    if not route:
        return 0.0
    # build from->to index arrays: depot (0) -> first, edges between nodes, last -> depot (0)
    from_idx = np.fromiter([0] + list(route), dtype=int)
    to_idx = np.fromiter(list(route) + [0], dtype=int)
    return float(self.distance_matrix[from_idx, to_idx].sum())
